  "check_code": "import hashlib
import re
import sqlite3
from datetime import date, datetime
from pathlib import Path

from docx import Document


TARGET_LIMIT = "LIM-HSBC-CQ5-RE-2024-HS-01"
TARGET_CYCLE = "REVIEW_2025_Q3_CONCENTRATION"
BRIEF_NAME = "HSBC_2025Q3_Real_Estate_Hard_Escalation_Brief.docx"


def _db(ws):
    return Path(ws).resolve().parent / "system" / "servicenow_irm" / "state.db"


def _norm(value):
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()


def _date(value):
    if value is None:
        return None
    text = str(value).strip()
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00")).date()
    except ValueError:
        try:
            return date.fromisoformat(text[:10])
        except ValueError:
            return None


def _target_rows(ws):
    with sqlite3.connect(_db(ws)) as connection:
        connection.row_factory = sqlite3.Row
        rows = connection.execute(
            """SELECT * FROM concentration_review_cases
               WHERE review_cycle_id=? AND source_limit_id=? AND case_status<>'Cancelled'""",
            (TARGET_CYCLE, TARGET_LIMIT),
        ).fetchall()
    return [dict(row) for row in rows]


def _brief_text(ws):
    path = Path(ws) / BRIEF_NAME
    if not path.exists():
        return None, ""
    document = Document(path)
    parts = [paragraph.text for paragraph in document.paragraphs]
    for table in document.tables:
        for row in table.rows:
            parts.extend(cell.text for cell in row.cells)
    return path, "\n".join(parts)


def _has_number(text, value, tolerance=0.0006):
    for token in re.findall(r"(?<![A-Za-z0-9])\d{1,3}(?:,\d{3})*(?:\.\d+)?", text):
        try:
            if abs(float(token.replace(",", "")) - value) <= tolerance:
                return True
        except ValueError:
            pass
    return False


def check_created_case_identity(ws):
    rows = _target_rows(ws)
    if len(rows) != 1:
        return {"score": 0, "detail": f"expected one non-cancelled Q3 case for the hard limit, found {len(rows)}"}
    row = rows[0]
    expected = {
        "review_cycle_id": TARGET_CYCLE,
        "institution_id": "ORG_HSBC_HOLDINGS_PLC",
        "forum_id": "FORUM_HSBC_GROUP_RISK_COMMITTEE",
        "source_limit_id": TARGET_LIMIT,
        "case_type": "Hard Escalation",
        "case_status": "Open",
    }
    mismatches = [key for key, value in expected.items() if _norm(row.get(key)) != _norm(value)]
    if mismatches:
        return {"score": 0, "detail": "incorrect case identity fields: " + ", ".join(mismatches)}
    return {"score": 1, "detail": f"created case {row['case_id']} has the required Q3 source and governance identity"}


def check_created_case_governance_timing(ws):
    rows = _target_rows(ws)
    if len(rows) != 1:
        return {"score": 0, "detail": "target case is missing or duplicated"}
    row = rows[0]
    expected_text = {
        "regulator_id": "REGULATOR_UK_PRA",
        "guidance_code": "PRA-RULEBOOK-CRR",
        "severity": "High",
    }
    mismatches = [key for key, value in expected_text.items() if _norm(row.get(key)) != _norm(value)]
    expected_dates = {
        "opened_at": date(2025, 9, 30),
        "decision_due_at": date(2025, 10, 2),
        "exception_expires_on": date(2025, 11, 15),
    }
    mismatches.extend(key for key, value in expected_dates.items() if _date(row.get(key)) != value)
    if mismatches:
        return {"score": 0, "detail": "incorrect governance or timing fields: " + ", ".join(mismatches)}
    return {"score": 1, "detail": "PRA guidance, High severity, two-business-day deadline, and expiry are correct"}


def check_brief_case_metrics(ws):
    _, text = _brief_text(ws)
    if not text:
        return {"score": 0, "detail": f"{BRIEF_NAME} is missing or empty"}
    rows = _target_rows(ws)
    if len(rows) != 1:
        return {"score": 0, "detail": "cannot link the brief to a unique created case"}
    normalized = _norm(text)
    required_tokens = [rows[0]["case_id"], TARGET_LIMIT, "gross carrying", "non performing", "early warning", "hard escalation"]
    missing = [token for token in required_tokens if _norm(token) not in normalized]
    # "distance" and "proximity" are equivalent labels for hard-limit headroom.
    if not any(label in normalized for label in ("headroom", "distance", "proximity")):
        missing.append("headroom/distance")
    required_numbers = [64.557, 4.687, 7.260, 6.500, 7.500, 0.760, 0.240]
    missing_numbers = [str(value) for value in required_numbers if not _has_number(text, value)]
    if missing or missing_numbers:
        return {"score": 0, "detail": f"brief missing tokens={missing} numbers={missing_numbers}"}
    return {"score": 1, "detail": "brief links the created case and presents all source, threshold, and headroom values"}


def check_brief_lineage_and_action(ws):
    _, text = _brief_text(ws)
    if not text:
        return {"score": 0, "detail": f"{BRIEF_NAME} is missing or empty"}
    normalized = _norm(text)
    lineage = all(_norm(token) in normalized for token in [
        "Adenza AxiomSL", "AXP-SNAP-2024-06-30-001", "AX-RUN-2024Q2-0612",
        "Archer", "ServiceNow",
    ]) and all(any(_norm(form) in normalized for form in forms) for forms in [
        ("June 30 2024", "30 June 2024"),
        ("September 30 2025", "30 September 2025"),
    ])
    overlay = any(label in normalized for label in ("management overlay", "management escalation overlay", "management review overlay")) and "published" in normalized and "pillar 3" in normalized and any(
        phrase in normalized for phrase in [
            "not a published", "not published", "not a new published",
            "not a newly published", "not presented as a new published",
            "does not represent", "must not be treated",
        ]
    )
    action = "committee" in normalized and any(word in normalized for word in ["approve", "endorse", "acknowledge", "ratify"]) and any(
        word in normalized for word in ["monitor", "monitoring"]
    ) and any(word in normalized for word in ["remediation", "portfolio reduction", "reduction plan"])
    no_false_breach = any(phrase in normalized for phrase in [
        "below the hard", "below hard", "not a hard threshold breach",
        "hard escalation not yet breached", "has not breached",
        "has not reached the hard", "not reached on current fact",
        "no article 395 breach", "not an observed crr article 395 breach",
    ])
    if not all([lineage, overlay, action, no_false_breach]):
        return {"score": 0, "detail": f"lineage={lineage}, overlay_distinction={overlay}, committee_action={action}, no_false_breach={no_false_breach}"}
    return {"score": 1, "detail": "brief preserves lineage, disclosure status, and below-threshold committee framing"}


def check_existing_cases_preserved(ws):
    baseline_ids = {
        "IRM-CONC-2024-0147", "IRM-CONC-2024-0163", "IRM-CONC-2024-0188", "IRM-CONC-2024-0196",
        "IRM-CONC-2025-0301", "IRM-CONC-2025-0304", "IRM-CONC-2025-0311", "IRM-CONC-2025-0317",
        "IRM-CONC-2025-0322", "IRM-CONC-2025-0328", "IRM-CONC-2025-0335", "IRM-CONC-2025-0341",
    }
    with sqlite3.connect(_db(ws)) as connection:
        connection.row_factory = sqlite3.Row
        rows = connection.execute("SELECT * FROM concentration_review_cases").fetchall()
        relevant = connection.execute("SELECT * FROM concentration_review_cases WHERE case_id='IRM-CONC-2025-0301'").fetchone()
    actual_ids = {row["case_id"] for row in rows}
    if not baseline_ids.issubset(actual_ids):
        return {"score": 0, "detail": "one or more pre-existing cases were deleted"}
    if relevant is None:
        return {"score": 0, "detail": "the prior real-estate quarterly case was deleted"}
    expected = {
        "review_cycle_id": TARGET_CYCLE,
        "institution_id": "ORG_HSBC_HOLDINGS_PLC",
        "forum_id": "FORUM_HSBC_GROUP_RISK_COMMITTEE",
        "source_limit_id": "LIM-IND-REAL-ESTATE-001",
        "case_type": "Quarterly Review",
        "regulator_id": "REGULATOR_UK_PRA",
        "guidance_code": "PRA_CRR_DISCLOSURE",
        "severity": "Moderate",
        "opened_at": "2025-07-07T08:42:00Z",
        "decision_due_at": "2025-09-25",
        "exception_expires_on": None,
        "case_status": "Resolved",
    }
    changed = [key for key, value in expected.items() if relevant[key] != value]
    if changed:
        return {"score": 0, "detail": "the existing real-estate review case was modified: " + ", ".join(changed)}
    return {"score": 1, "detail": "all baseline case IDs remain and the relevant historical case is unchanged"}


def check_source_files_preserved(ws):
    expected = {
        "HSBC_2025Q3_Concentration_Risk_Analysis.xlsx": "66abc358730d19b1b25e85c0b438aad7416338a86f1f57f212f1b09023c1be42",
        "HSBC_2025Q3_Concentration_Risk_Report.docx": "d1b41ce8eb8bda273fb715c59d3ce5ff37962b02084d7fd3b1944824fa51db32",
        "HSBC_2025Q3_Group_Risk_Committee_Concentration_Review.pptx": "6136dd7147c13c2ab1d435069299950e4c80a3c25112e94d42be28ea32a44380",
        "eba_large_exposure_breaches_2021.pdf": "799db6ed0fed56c9de94c29548aecdc90779a31f22a41e01edd37cfb8bc32b16",
        "hsbc_2q2024_data_pack.xlsx": "43b194722780b2edc7c5d340f604858500f22f9c655c53c3056163abddf48862",
        "hsbc_pillar3_2024-06-30.pdf": "fb3d8aba1d525876971e68a21e17f4d6e3f7765b397a9ce87c53902f56a0b6a5",
        "hsbc_pillar3_2025-03-31.pdf": "44b3475381c124d82f8758f806b205bfe48916ad3e997c90c1b972bc016ca0fd",
    }
    failures = []
    for name, digest in expected.items():
        path = Path(ws) / name
        if not path.exists() or hashlib.sha256(path.read_bytes()).hexdigest() != digest:
            failures.append(name)
    if failures:
        return {"score": 0, "detail": "protected source files changed or disappeared: " + ", ".join(failures)}
    return {"score": 1, "detail": "all seven protected workspace sources remain unchanged"}
